type WorkerProposal = { id: string; status: 'pending'|'dispatching'|'dispatched'; text: string; orchestratorAssignmentId: string; createdAt: string; workerAssignmentId?: string; workerAssignmentHistoryIds?: string[];workspaceId?:string;pinnedBaseCommit?:string };
type OrchestratorInbox = { id: string; status: 'received'; runId: string; sessionLocalId: string; sessionId?: string; workerAssignmentId: string; workerResponseId: string; pinnedBaseCommit: string; allowedScope: string[]; reviewDiff: string; validation: { passed: boolean; observations?: ValidationObservation[] }; evidenceDigest: string; receivedAt: string; deliveredInAssignmentId?: string };
