type Review = { id: string; status?: 'proposed'|'verified'; reviewerAssignmentId: string; implementationAssignmentIds: string[]; verdict: 'clear'|'changes_requested'|'rejected'; scope: string[]; summary: string; createdAt: string };
type WorkerEvidence = { provenance?: 'bridge_snapshot'|'recorded_replay'|'recorded_live_import'; workerAssignmentId?: string; workspaceId?:string; responseId?: string; requestedModel?: string; actualModel?: string; actualModelStatus?: 'observed'|'unavailable'; cliInvocation?: {executable:string;hostExecutable?:string;args:string[]}; usage?: UsageMetrics; pinnedBaseCommit?: string; completeSnapshot?: {reportedComplete:boolean;reportedErrors:number;entryCount:number}; scopeVerified?: boolean; allowedScope?: string[]; entries?: Array<{path?:string;kind?:string;sha256?:string;size?:number;mode?:string}>; changes?: Array<{path?:string;previousPath?:string;kind?:string;summary?:string}>; reviewDiff?: string; acceptance?: string };
