type ReviewerRecommendation = { id?: string; provenance?: 'uhp_response'|'simulated_fixture'; harnessId?: string; model?: string; actualModel?: string; reviewMode?: string; mutationAttempted?: boolean; responseId?: string; sessionId?: string; usage?: UsageMetrics; reviewerAssignmentId?: string; verdict?: 'recommend'|'request_changes'|'reject'|'unparsed'; rationale?: string; createdAt?: string };
type Approval = { id: string; approved: boolean; decision?: 'approved'|'rejected'; evidenceCommit?: string; evidenceDigest?: string; rationale?: string; createdAt: string };
type Promotion = { status: 'not_started'|'promoting'|'applied'|'failed'; operationId?: string; evidenceDigest?: string; destinationBranch?: string; resultCommit?: string; resultTree?: string; error?: string; updatedAt?: string };
type RejectedWorkerAttempt = {id:string;proposal:WorkerProposal;workerAssignmentId:string;workspaceId?:string;pinnedBaseCommit?:string;responseId?:string;usage?:UsageMetrics;reason:string;evidenceStatus:'rejected_untrusted';createdAt:string};
type Session = { localId: string; roleId: string; generation: number; status: string; config: RoleConfig; uhpSessionId?: string; responseId?: string; startedAt: string };
type RunBudgets = { roleTurns: {planner:number;orchestrator:number;worker:number;reviewer:number}; workerAttempts:number };
type Run = { id: string; status?: string; controller?: {startedAt?:string;phase?:'orchestrating'|'dispatching'|'verifying'|'validating'|'reviewing'|'stopped'|'awaiting_approval';budgets?:RunBudgets;stoppedReason?:string;active?:boolean}; reviewerRetryAuthorized?:boolean; pinnedBaseCommit?: string; workspaceId?: string; plannerSessionId?: string; orchestratorSessionId?: string; sessions?: {planner?:Session;orchestrator?:Session}; roleConfigs?: Record<string,RoleConfig>; usage?: UsageMetrics; usageByRole?: Record<string,UsageMetrics>; usageByHarnessModel?: Record<string,UsageMetrics>; guidance?: Guidance[]; workerProposal?: WorkerProposal; workerProposalHistory?:WorkerProposal[]; rejectedWorkerAttempts?:RejectedWorkerAttempt[]; orchestratorInbox?: OrchestratorInbox; orchestratorInboxHistory?: OrchestratorInbox[]; assignments?: Assignment[]; reviews?: Review[]; workerEvidence?: WorkerEvidence; workerEvidenceHistory?: WorkerEvidence[]; reviewerRecommendation?: ReviewerRecommendation; reviewerRecommendationHistory?: ReviewerRecommendation[]; validation?: Validation; validationHistory?: Validation[]; approval?: Approval; promotion?: Promotion; createdAt?: string; updatedAt?: string };
type PlannerMessage = { id:string; role:'user'|'planner'; text:string; createdAt:string; assignmentId?:string; createdTaskIds?:string[] };
