export type Task = { id: string; title: string; goal?:string; suggestedAllowedPaths?:string[]; validationCriteria?:string[]; dependsOn?:string[]; status?: string; planApproval?:{status:'approved';approvedAt:string;specDigest:string;runId:string}; runs?: Run[] };
export type Project = { id: string; name: string; repoPath?:string; status?: string; plannerSession?:Session; plannerMessages?:PlannerMessage[]; plannerAssignments?:Assignment[]; plannerTurnCount?:number; defaultRoleConfigs?: Record<string,RoleConfig>; usage?: UsageMetrics; usageByHarnessModel?: Record<string,UsageMetrics>; tasks?: Task[] };
type RepoEntry={name:string;path:string;isGitRepo:boolean};
type RepoBrowse={currentPath:string;parentPath?:string;entries:RepoEntry[];roots:{name:string;path:string}[];truncated:boolean};
type WorkspaceSetup={repoPath:string;head:string;dirty:boolean;allowedScope:string[];validationCommands:{name:string;command:string;args:string[]}[];bridgeStatus?:string};
export type TaskStartPreview={taskId?:string;task?:Task;roleConfigs?:Record<string,RoleConfig>;scope?:string[];validationCriteria?:string[];validationCommands?:{name:string;command:string;args:string[]}[];budgets?:RunBudgets;baseCommit?:string;currentHead?:string;requiredBaseCommits?:string[];requiresExplicitBase:boolean;reasons?:string[];overlappingTaskIds?:string[];dependencyTaskIds?:string[];dependencies?:Task[];canStart?:boolean};
