  const taskRoleReady=(role:typeof taskRoleIds[number])=>{const config=taskAdvancedEdited?roleChoices[role]:taskStartPreview?.roleConfigs?.[role],definition=state.roles?.find(item=>item.id===role),choices=definition?.availableConfigs??[];return Boolean(definition?.enabled&&config?.harnessId&&config?.model&&(!choices.length||choices.some(choice=>configKey(choice)===configKey(config))))};
  const taskRoleDefaultsReady=taskRoleIds.every(taskRoleReady);
  const taskReadyRoleCount=taskRoleIds.filter(taskRoleReady).length;
