  const adminActionInfo=adminAction?(()=>{const actionProject=state.projects.find(p=>p.id===adminAction.projectId);const actionTask=actionProject?.tasks?.find(t=>t.id===adminAction.taskId);switch(adminAction.kind){case'delete-project':return {title:'Delete project?',description:`Delete “${actionProject?.name??'this project'}” and erase all of its tasks and runs? Its repository will no longer appear in Foreman. Historical deletion events remain in activity.`,confirm:'Delete project',danger:true};case'delete-task':return {title:'Delete task?',description:`Delete “${actionTask?.title??'this task'}” and remove its ${actionTask?.runs?.length??0} run records? Historical deletion events remain in activity.`,confirm:'Delete task',danger:true};case'reset-planner':return {title:'Reset Planner conversation?',description:`Clear the Planner conversation and its session for “${actionProject?.name??'this project'}”. Tasks, runs, and repository settings stay in place.`,confirm:'Reset Planner conversation',danger:false};case'reset-plan':return {title:'Reset approved plan?',description:`Remove the approved plan for “${actionTask?.title??'this task'}”. You can review and approve a plan again.`,confirm:'Reset approved plan',danger:false};}})():undefined;
  useEffect(()=>{setSelectedWorkflowRole(workflowRoleForPhase(initialWorkflowPhase?.id));setSelectedWorkflowPhase(initialWorkflowPhase?.id);},[task?.id,run?.id]);
  const streamActivity=streamingActivityRows();
